import { Container, Texture } from 'pixi.js';

import { AssetManager, AssetRegion, IAssetConfig, IAssetList, IBaseAssetConfig, ISoundAssetConfig } from '@game-studio/asset-manager';
import { Device } from '@game-studio/device';
import { Locale } from '@game-studio/utilities';

import { cabinetAssetList } from './assets/asset-list';
import { CabinetLayoutState, CabinetUserPrefs, ComponentVisibility, IAutoPlayText, ICabinetButtonTextConfig, ICabinetButtonTexts, ICabinetConfig, ICabinetDimensions, ICabinetInteractionMethods, ICabinetLayoutInfo, ICabinetMessage, IRequiredStrings, IStake, IVisibility, OneHandedPlaySetting, OneHandedPlaySettingStrings } from './types/cabinet';
import { AutoPlayView } from './views/auto-play';
import { CabinetView } from './views/cabinet-view';
import { HTPNudgeState } from './views/htp-info/htp-nudge';

export { cabinetAssetList as cabinetAssetList } from './assets/asset-list';
export * from './types/cabinet';
export { CabinetButtonView } from './views/buttons/cabinet-button';

export default abstract class Cabinet extends Container {

    /** @deprecated Changing the GameInfo Visibility is no longer supported as its visibly the entire time.  */
    public set gameInfoComponentVisibility(visibility: IVisibility) {
        // No Implementation
    }

    /** @deprecated The clock is no longer supported in the cabinet, and has been moved to the session overlays. */
    public set clockVisibility(visibility: ComponentVisibility) {
        // No Implementation
    }

    /** @deprecated Renamed to loadingSpinnerDelay matching what it actually returns */
    public set loadingSpinnerDuration(seconds: number) {
        this._cabinetView.actionButton.loadingSpinnerDelay = seconds;
    }

    /** the time in MS the loading spinner should wait before displaying on slow purchase responses */
    public set loadingSpinnerDelay(seconds: number) {
        this._cabinetView.actionButton.loadingSpinnerDelay = seconds;
    }

    public set holdSpinnerDuration(seconds: number) {
        this._cabinetView.actionButton.holdSpinnerDuration = seconds;
    }

    public set gameInfoTexture(newTexture: Texture) {
        this._cabinetView.infoButton.changeButtonTexture(newTexture);
    }

    public get autoPlayPopupVisible(): boolean {
        return this._autoPlayView.visible;
    }

    public get inFreePlay(): boolean {
        return this._inFreePlay;
    }

    /**
     * Returns the physical dimensions of the cabinet
     *
     * Position is based on the top left corner
     *
     * Anchored state excludes the action button
     *
     * Floating state includes the action button
     */
    public get CabinetDimensions(): ICabinetDimensions {
        if (!this._cabinetView) {
            return {
                x: 0,
                y: 0,
                width: 0,
                height: 0
            };
        } else {
            return this._cabinetView.dimensions;
        }
    }

    protected get gameInfoTouchStartTime(): number {
        return this._cabinetView.infoButton.touchStartTime;
    }

    protected get settingsTouchStartTime(): number {
        return this._cabinetView.settingsButton.touchStartTime;
    }

    /**
     * Returns the current state of the HTP nudge (internal use only)
     */
    protected get htpNudgeState(): HTPNudgeState {
        return this._cabinetView.htpNudge.state;
    }

    protected _loadPromise: Promise<void> | null = null;
    private _device: Device;
    private _gameWidth: number;
    private _gameHeight: number;
    protected _userPrefs: CabinetUserPrefs;
    private _purchaseTimer!: number;
    protected _cabinetView: CabinetView;
    private _cabinetInteractionMethods: ICabinetInteractionMethods;
    private _autoPlayView!: AutoPlayView;
    private _strings: IRequiredStrings;
    private _locale: Locale;
    protected _cabinetConfig: ICabinetConfig;

    private _inFreePlay: boolean = false;
    protected _layoutState: CabinetLayoutState = 'floating';
    protected _isScalingLayoutEnabled: boolean = false;
    protected _scalingLayoutWidthFraction: number = 0.12;
    protected _scalingLayoutGapMultiplier: number = 0.3;

    constructor(device: Device, userPrefs: CabinetUserPrefs, cabinetConfig: ICabinetConfig, locale: Locale) {
        super();

        this._device = device;
        this._userPrefs = userPrefs;
        this._cabinetConfig = cabinetConfig;
        this._locale = locale;

        this.name = 'cabinet';
    }

    /**
     * Loads the assets for the cabinet
     * @param assetEndpoint The endpoint to load assets from
     * @param onProgress A callback function to track loading progress
     * @returns A promise that resolves with the loaded resources
     */
    public async loadAssets(baseUrl: string, onProgress?: (progress: number) => void): Promise<void> {
        if (this._loadPromise !== null) {
            return this._loadPromise;
        }

        const regionAssetList = this.overrideRegionalAssets(baseUrl);
        return this._loadPromise = new Promise<void>(async (resolve) => {
            await AssetManager.load(regionAssetList, onProgress);
            resolve();
        });
    }

    /**
     * Initialises the cabinet, should be called once after the cabinet has been newed up
     * @returnType {Promise<void>}
     */
    public init(strings: IRequiredStrings): Promise<void>;
    public init(strings: IRequiredStrings, gameWidth: number, gameHeight: number): Promise<void>;
    public async init(strings: IRequiredStrings, arg2?: number, arg3?: number): Promise<void> {
        let gameWidth: number | undefined = undefined;
        let gameHeight: number | undefined = undefined;

        if (arg2 !== undefined && arg3 !== undefined) {
            gameWidth = arg2;
            gameHeight = arg3;
        }

        this._strings = strings;
        this._gameWidth = gameWidth ?? this._device.viewport.width;
        this._gameHeight = gameHeight ?? this._device.viewport.height;

        await this.onLoaded();
    }

    /**
     * Changes the cabinet layout based on one handed play setting
     */
    public changeCabinetLayout(oneHandedSetting: OneHandedPlaySetting | OneHandedPlaySettingStrings): void {
        if (this._cabinetView !== undefined) {
            this._cabinetView.oneHandedPlaySetting = oneHandedSetting;
        }
        if (this._autoPlayView !== undefined) {
            this._autoPlayView.oneHandedPlaySetting = oneHandedSetting;
            this._autoPlayView.onLayoutChange(this.getCabinetLayoutInfo(), this._layoutState);
        }
    }

    /**
     * Enables the purchase button to be interactable
     */
    public enablePurchaseButton(): void {
        this._cabinetView.actionButton.enable(true);
    }

    /**
     * Enables the interactivity without changing anything else
     */
    public enablePurchaseButtonInteractivity(): void {
        this._cabinetView.actionButton.interactionEnabled = true;
    }

    /**
     * Prevents the user from interacting with the purchase button
     */
    public disablePurchaseButton(options: { shouldScale: boolean } = { shouldScale: true }): void {
        this._cabinetView.actionButton.enable(false, options.shouldScale);
    }

    /**
     * Disables the interactivity without changing anything else
     */
    public disablePurchaseButtonInteractivity(): void {
        this._cabinetView.actionButton.interactionEnabled = false;
    }

    /**
     * Hides the purchase button
     */
    public hideActionButton(): void {
        this._cabinetView.showActionButton(false);
    }

    /**
     * Shows the purchase button
     */
    public showActionButton(): void {
        this._cabinetView.showActionButton(true);
    }

    /**
     * Hides both the plus and minus buttons
     */
    public hideStakeButtons(): void {
        this._cabinetView.showStakeButtons(false);
    }

    /**
     * Shows both the plus and minus buttons
     */
    public showStakeButtons(): void {
        this._cabinetView.showStakeButtons(true);
    }

    /**
     * Enables both the plus and minus buttons
     */
    public enableStakeButtons(): void {
        this.enablePlusButton();
        this.enableMinusButton();
    }

    /**
     * Disables both the plus and minus buttons
     */
    public disableStakeButtons(): void {
        this.disablePlusButton();
        this.disableMinusButton();
    }

    /**
     * Enables responsive button scaling and positioning based on game width (portrait floating layout).
     * When enabled, buttons scale proportionally to the screen width for consistent visual sizing.
     */
    public enableScalingLayout(): void {
        this._isScalingLayoutEnabled = true;
        this.handleOrientationChange(this._gameWidth, this._gameHeight);
    }

    /**
     * Disables responsive button scaling, reverting to legacy fixed-size behavior.
     * When disabled, buttons are scaled relative to the cabinet bar height.
     */
    public disableScalingLayout(): void {
        this._isScalingLayoutEnabled = false;
        this.handleOrientationChange(this._gameWidth, this._gameHeight);
    }

    /**
     * Enables just the plus button
     */
    public enablePlusButton(): void {
        if (!this.inFreePlay) {
            this._cabinetView.increaseStakeButton.enable(true);
        }
    }

    /**
     * Disables just the plus button
     */
    public disablePlusButton(): void {
        this._cabinetView.increaseStakeButton.enable(false);
    }

    /**
     * Enables just the minus button
     */
    public enableMinusButton(): void {
        if (!this.inFreePlay) {
            this._cabinetView.decreaseStakeButton.enable(true);
        }
    }

    /**
     * Disables just the minus button
     */
    public disableMinusButton(): void {
        this._cabinetView.decreaseStakeButton.enable(false);
    }

    /**
     * Enables the game info button, making it clickable
     */
    public enableGameInfoButton(): void {
        this._cabinetView.infoButton.enable(true);
    }

    /**
     * Disables the game info button, making it no longer clickable
     */
    public disableGameInfoButton(): void {
        this._cabinetView.infoButton.enable(false);
    }

    /**
     * Disables all buttons bar the settings button
     */
    public disableAll(): void {
        this.disablePurchaseButton();
        this.disablePlusButton();
        this.disableMinusButton();
        this.disableGameInfoButton();
    }

    /**
     * Hides the entire cabinet
     */
    public hide(): void {
        this.visible = false;
    }

    /**
     * Shows the entire cabinet
     */
    public show(): void {
        this.visible = true;
    }

    /**
     * Updates the text shown on the purchaseButton
     * @param newText {string} the text to update to
     */
    public updatePurchaseText(newText: string): void {
        this._cabinetView.actionButton.updateStakeText(newText);
    }

    /**
     * Hides the purchase text on the purchase button
     */
    public hidePurchaseText(): void {
        this._cabinetView.actionButton.showStake = false;
    }

    /**
     * Shows the purchase text on the purchase button
     */
    public showPurchaseText(): void {
        this._cabinetView.actionButton.showStake = true;
    }

    /**
     * Updates the message in the message box of the cabinet, if an amount is specified the message is appended to the message with spacing in landscape and split to a new line in portrait
     * @param message {ICabinetMessage} the message to update to in portrait or landscape orientation
     * @param instant {boolean} wether the message should update instantly or animate
     */
    public setCabinetMessage(message: ICabinetMessage, instant: boolean = false): void {
        this._cabinetView.messageComponent.setText(message, !instant);
    }

    public setUnAuthDemoBalance(balanceText: string): void {
        this._cabinetView.balanceComponent.setIcon(null);
        // this._cabinetView.balanceComponent.toggleLabel(false);
        this._cabinetView.balanceComponent.setText({ portrait: balanceText, landscape: balanceText }, true);
    }

    /**
     * Updates the displayed balance, does not format it to show £'s and p's
     * @param amount {string} the balance amount
     */
    public setCurrentBalance(amount: string): void {
        this._cabinetView.balanceComponent.setIcon(null);
        this._cabinetView.balanceComponent.setText({ portrait: amount, landscape: amount }, true);
    }

    public setFreePlayBalance(amount: number): void {
        this._cabinetView.balanceComponent.setIcon('free-play-icon');
        this._cabinetView.balanceComponent.setText({ portrait: ': ' + amount, landscape: ': ' + amount }, true);
    }

    public enterFreePlay(config: ICabinetButtonTextConfig): void {
        this._cabinetView.actionButton.enterFreePlay(config);
        this._inFreePlay = true;
        this.disableStakeButtons();
    }

    public clearInFreePlay(): void {
        this._inFreePlay = false;
        this.resetPurchaseTexture();
    }

    /**
     * Updates the text strings shown on the auto play popup
     * @param textSet {IAutoPlayText} the object with all the required strings for the popup
     */
    public setAutoPlayText(textSet: IAutoPlayText): void {
        this._autoPlayView.setText(textSet);
    }

    /**
     * Updates the texture of the purchase button
     * @param newTexture {Texture} the new texture for the purchase button
     */
    public updatePurchaseTexture(newTexture: Texture): void {
        if (newTexture.uid === this._cabinetView.actionButton.defaultTexture.uid) {
            this._cabinetView.actionButton.resetButtonTexture();
        } else {
            this._cabinetView.actionButton.changeButtonTexture(newTexture);
        }
    }

    public updatePurchaseMainText(textConfig: ICabinetButtonTextConfig): void;
    public updatePurchaseMainText(textKey: keyof ICabinetButtonTexts): void;
    public updatePurchaseMainText(arg1: ICabinetButtonTextConfig | keyof ICabinetButtonTexts): void {
        const textConfig = typeof arg1 === 'object' ? arg1 : this._cabinetConfig.buttonTexts[arg1];
        this._cabinetView.actionButton.updateMainText(textConfig.message, textConfig.position, textConfig.fontSize);
    }

    public updateStyles(): void {
        this._cabinetView.actionButton.updateMainTextStyle(this._cabinetConfig);
        this._cabinetView.messageComponent.updateTextStyle(this._cabinetConfig);
        this._cabinetView.balanceComponent.updateTextStyle(this._cabinetConfig);
    }

    /**
     * Updates the texture of the purchase button
     * @param newTexture {Texture} the new texture for the purchase button
     */
    public resetPurchaseTexture(): void {
        this._cabinetView.actionButton.resetButtonTexture();
    }

    /**
     * Changes the displayed stake value and then animates as though the user has changed stake
     * @param text {string} the stake value to update to
     */
    public animateStakeText(text: string): void {
        this._cabinetView.actionButton.updateStakeText(text);
    }

    /**
     * Hides the loading spinner around the action button
     */
    public hideLoadingSpinner(): void {
        this._purchaseTimer && window.clearTimeout(this._purchaseTimer);
        this._cabinetView.actionButton.showLoadingSpinner = false;
    }

    /**
     * Shows the loading spinner around the action button
     * @param delay {number} the time in milliseconds to wait before showing the loading spinner, if the delay is 0 the spinner will show immediately
     */
    public showLoadingSpinner(delay: number = 0): void {
        this._purchaseTimer && window.clearTimeout(this._purchaseTimer);

        this._purchaseTimer = window.setTimeout(() => {
            this._cabinetView.actionButton.showLoadingSpinner = true;
        }, delay);
    }

    /**
     * Shows the action hold spinner around the action button
     */
    public showActionHoldSpinner(): void {
        this._cabinetView.actionButton.showActionHoldSpinner = true;
    }

    /**
     * Hides the action hold spinner around the action button
     */
    public hideActionHoldSpinner(): void {
        this._cabinetView.actionButton.showActionHoldSpinner = false;
    }

    /**
     * Shows the auto play popup
     */
    public showAutoPlayPopup(): void {
        this._autoPlayView.show();
    }

    /**
     * Hides the auto play popup
     */
    public hideAutoPlayPopup(): void {
        this._autoPlayView.hide();
    }

    /**
     * @deprecated Flashing a message is no longer supported due to the redesign of the cabinet.
     * Flashes the message box if the isWinner parameter is true
     * @param isWinner {boolean} whether the game was a win or not
     */
    public flashMessage(): void {
        // No Implementation
    }

    /**
     * Triggers the bounce animation for the action button
     */
    public bounceActionButton(): void {
        this._cabinetView.actionButton.bounce();
    }

    /**
     * Resets the cabinet to its default state, 'not bought in' and enables both of the stake buttons
     */
    public reset(stake: IStake): void {
        this._cabinetView.actionButton.resetButtonTexture();
        this.enablePurchaseButton();
        this.updateStakeButtons();
        if (stake) {
            this._cabinetView.actionButton.updateStakeText(stake.stake);
        }
    }

    /**
     * Destroys the cabinet and its children
     */
    public destroy(): void {
        this._destroyChildren();
        super.destroy();
    }

    /**
     * Should be called when the user changes orientation, updates the sizes of each of the elements of the cabinet to handle the new screen size
     */
    public handleOrientationChange(gameWidth: number, gameHeight: number): void {
        this._gameWidth = gameWidth;
        this._gameHeight = gameHeight;

        this.setCabinetOverrides();

        if (this._cabinetView) {
            this._cabinetView.isScalingLayoutEnabled = this._isScalingLayoutEnabled;
            this._cabinetView.scalingLayoutWidthFraction = this._scalingLayoutWidthFraction;
            this._cabinetView.scalingLayoutGapMultiplier = this._scalingLayoutGapMultiplier;
            this._cabinetView.onOrientationChange(this._gameWidth, this._gameHeight);
        }
        if (this._autoPlayView) { this._autoPlayView.onOrientationChange(this.getCabinetLayoutInfo(), this._layoutState); }
    }

    protected updatePurchaseLayout(purchaseLayout: CabinetLayoutState): void {
        this._layoutState = purchaseLayout;

        this._cabinetView.setLayout(purchaseLayout);
        this._autoPlayView.onLayoutChange(this.getCabinetLayoutInfo(), this._layoutState);
    }

    /** Shows the HTP Nudge Popup (internal use only) */
    protected showHTPNudge(): void {
        this._cabinetView.htpNudge.animateOn();
    }

    /** Hides the HTP Nudge Popup (internal use only) */
    protected hideHTPNudge(): void {
        this._cabinetView.htpNudge.animateOff();
    }

    /** Permanently dismisses the HTP Nudge - it will never show again (internal use only) */
    protected dismissHTPNudge(): void {
        this._cabinetView.htpNudge.dismiss();
    }

    /**
     * This method is called when the user simply clicks the Action Button (Pointer Down and Pointer Up), calling this will trigger the loading spinner
     */
    protected onActionButtonClick(): void {
        this.showLoadingSpinner(this.loadingSpinnerDelay);
    }

    /**
     * This method is called when the user holds their click on the action button (Mouse down), calling super on this will do nothing as there is no base implementation necessary
     */
    protected onActionButtonHold(): void {
        // No Implementation necessary
    }

    /**
     * This method is called when the user stops holding their click on the action button (Mouse Up), calling super on this will do nothing as there is no base implementation necessary
     */
    protected onActionButtonHoldEnd(): void {
        // No Implementation necessary
    }

    /**
     * This method is called when the user stops holding their click on the action button (Mouse Up) outside of the actual button, calling super on this will do nothing as there is no base implementation necessary
     */
    protected onActionButtonHoldEndOutside(): void {
        // No Implementation necessary
    }

    /**
     * This method is called when the confirm button on the auto play popup is clicked. Calling super on this will do nothing as there is no base implementation necessary
     */
    protected onAutoPlayConfirmClick(): void {
        // No Implementation necessary
    }

    /**
     * This method is called when the cancel button on the auto play popup is clicked. Calling super on this will do nothing as there is no base implementation necessary
     */
    protected onAutoPlayCancelClick(): void {
        // No Implementation necessary
    }

    /**
     * This method is called when the user clicks the Game Info Button, calling super on this will do nothing as there is no base implementation necessary
     */
    protected onGameInfoClick(): void {
        // No Implementation necessary
    }

    /**
     * Does nothing by default. This method should be overwritten when the user wishes to ensure that overrides occur during orientation change
     */
    protected setCabinetOverrides(): void {
        // No base Implementation necessary
    }

    /**
     * This method is called when the user clicks the settings Button
     */
    protected abstract onSettingsButtonClick(): void;

    /**
     * This method is called when the user clicks the increase stake button
     * @returnType {IStake}
     */
    protected abstract onIncreaseStakeClick(): IStake;

    /**
     * This method is called when the user clicks the decrease stake button and should return an object containing the formatted stake and the stake in raw pennies
     * @returnType {IStake}
     */
    protected abstract onDecreaseStakeClick(): IStake;

    /**
     * This method is called when in each game to enable the stake buttons, should only enable + and - if they're available
     */
    protected abstract updateStakeButtons(): void;

    /**
     * This method is provided by the user and should return an object containing the formatted stake and the stake in raw pennies
     * @returnType {IStake}
     */
    protected abstract getStake(): IStake;

    private bindInteractionMethods(): Promise<void> {
        return new Promise((resolve) => {
            this._cabinetInteractionMethods = {
                onActionButtonClick: this.onActionButtonClick.bind(this),
                onActionButtonHold: this.onActionButtonHold.bind(this),
                onActionButtonHoldEnd: this.onActionButtonHoldEnd.bind(this),
                onActionButtonHoldEndOutside: this.onActionButtonHoldEndOutside.bind(this),
                onAutoPlayConfirmClick: this.onAutoPlayConfirmClick.bind(this),
                onAutoPlayCancelClick: this.onAutoPlayCancelClick.bind(this),
                onDecreaseStakeClick: this.onDecreaseStakeClick.bind(this),
                onGameInfoClick: this.onGameInfoClick.bind(this),
                onIncreaseStakeClick: this.onIncreaseStakeClick.bind(this),
                onSettingsButtonClick: this.onSettingsButtonClick.bind(this)
            };
            resolve();
        });
    }

    private _destroyChildren(): void {
        this.removeChildren();

        this._cabinetView.actionButton.destroy();
        this._cabinetView.increaseStakeButton.destroy();
        this._cabinetView.decreaseStakeButton.destroy();
        this._cabinetView.messageComponent.destroy();
        this._cabinetView.balanceComponent.destroy();
        this._cabinetView.destroy();
    }

    private onLoaded(): Promise<void> {
        return this.bindInteractionMethods()
            .then(() => {
                this._cabinetView = new CabinetView(this._device, this._strings, this._cabinetInteractionMethods, this._userPrefs, this.getStake.bind(this));
                this._cabinetView.name = 'cabinet-view';

                this._autoPlayView = new AutoPlayView(this._device, this._cabinetInteractionMethods, this._userPrefs);
                this._autoPlayView.name = 'auto-play-view';

                this.addChild(this._cabinetView);
                this.addChild(this._autoPlayView);
                return;
            });
    }

    private getCabinetLayoutInfo(): ICabinetLayoutInfo {
        return {
            position: { x: this._cabinetView.position.x, y: this._cabinetView.position.y },
            backgroundWidth: this._cabinetView.backgroundWidth,
            backgroundHeight: this._cabinetView.backgroundHeight,
            // Uses the custom dimensions getter rather than the native Container.height, which is bounds-based and can report Infinity before the first render pass
            height: this._cabinetView.dimensions.height,
            dimensionsY: this._cabinetView.dimensions.y,
            increaseStakeButton: {
                x: this._cabinetView.increaseStakeButton.position.x,
                width: this._cabinetView.increaseStakeButton.width
            },
            decreaseStakeButton: {
                x: this._cabinetView.decreaseStakeButton.position.x,
                width: this._cabinetView.decreaseStakeButton.width
            }
        };
    }

    private overrideRegionalAssets(baseUrl: string): IAssetConfig {
        const assetConfig: IAssetConfig = {
            baseUrl,
            assetList: {},
            skin: 'core',
            version: 'cabinet'
        };

        const assetRegions: AssetRegion[] = this._locale !== 'en-gb' ? ['international', this._locale] : [this._locale];

        for (const key in cabinetAssetList.default) {
            const typedKey = key as keyof IAssetList;

            if (typedKey === 'webFonts') { continue; }

            const assetType = cabinetAssetList.default[typedKey];

            if (assetType === undefined) { continue; }

            assetType.forEach(assetData => {
                const assetListEntry: (ISoundAssetConfig | IBaseAssetConfig)[] = assetConfig.assetList[typedKey] ?? [];

                let newAssetEntry = assetData;
                for (let i = assetRegions.length - 1; i >= 0; i--) {
                    const region = assetRegions[i];
                    const regionalOverrides = cabinetAssetList[region];
                    if (regionalOverrides) {
                        const regionalOverride = regionalOverrides[typedKey];

                        if (regionalOverride) {
                            const assetEntry = regionalOverride.find((assetEntry) => { return assetEntry.name === assetData.name; });
                            if (assetEntry !== undefined) {
                                newAssetEntry = assetEntry;
                                break;
                            }
                        }
                    }
                }

                // removes the isLazyLoad flag as we've already handled that
                // and don't want the asset manager to do it's native lazy load approach
                newAssetEntry.isLazyLoad = undefined;

                (assetListEntry as unknown[]).push(newAssetEntry);

                (assetConfig.assetList[typedKey] as unknown) = assetListEntry;
            });
        }

        return assetConfig;
    }
}

